SUMMER = ["season:summer"]
STPATS = ["holiday:st-patricks-day"]

PACK = [
    # ---------------- Seasons, just teens (seasons age-13/14 primary 8 -> 9) ----------------
    A("growing-degree-day-ledger", "Growing Degree-Day Ledger",
      "Teens keep a season's heat accounts: daily temperatures become growing degree-days, a budburst prediction is written down, and the plants grade it.",
      ["seasons"], (13, 14), (4, 16), (45, 60), ["outdoor"],
      ["one max-min thermometer, or the site's agreed weather source read at the same hour every day (the ledger's whole honesty is sameness: same source, same hour, same handwriting in the temperature columns — a prediction built on mixed sources is a rumour with arithmetic on it)", "the ledger itself — a hardback book ruled before the season starts: date, high, low, mean, the day's degree-days, the running total, and a predictions page whose entries are dated and never altered, only graded", "one named event to predict, chosen for being observable from the site's own ground (a named tree's budburst, a bed's first flower, the lilac by the gate — something the crew can check with their own eyes on a stated round, not a photograph sent by somebody else)", "the base-temperature card for the chosen plant, agreed with the adults from a trusted gardening source and copied onto the ledger's first page word for word (plants count heat above their own base, and the base is a fact about the plant, not a number the crew negotiates)"],
      False, "Choose the event before you open the ledger, and choose it the way forecasters choose: near enough to check on foot, sharp enough to grade without argument — budburst on a named branch, first open flower on a named shrub — and write its definition on the predictions page now, in the plainest words the crew owns, because a prediction whose event is fuzzy can never be wrong, and a prediction that can never be wrong is worth nothing. Set the ledger's law at setup and write it on the first page: temperatures are entered daily at the stated hour from the stated source, a missed day is entered as missed and estimated never, and predictions are written in ink, dated, and signed — a graded miss in ink teaches more than a pencilled success rewritten after the fact. Work one example day together before the season starts: high, low, mean, minus the base, floored at zero — the arithmetic is small and the crew does it by hand all season, because a spreadsheet that computes silently teaches nobody where degree-days come from. Agree the checking round now: who walks to the named plant on which days, and what they report back — seen, not seen, or nearly — in the ledger's own three words.",
      ["The framing, at the ledger's table, the named plant in view if the ground allows: 'A plant keeps its calendar in heat, not in dates. The shrub by the gate does not know what April is. It knows how much warmth has arrived since winter — it adds the days up in its own arithmetic, and when the sum crosses its number, it opens. Farmers and growers have kept that arithmetic for centuries, and it has a name: growing degree-days. Every day gives the plant a payment — the day's mean temperature, minus the base below which this plant counts nothing — and the payments accumulate in this ledger, in our handwriting, at the same hour, from the same source, all season. When our running total approaches the sum the references say this event usually needs, this crew will do the brave thing in ink: predict the date. Then the plant grades us. Not kindly, not cruelly — exactly. A crew that has predicted a budburst and been graded by the bush itself has learned the difference between a forecast and a feeling, and that difference is the whole of this record.' The base card is read aloud, the first day's temperatures are entered together, and the ledger's law is signed by the crew.",
       "The daily entries, the ledger's long quiet discipline: each day's high and low are entered at the stated hour by the rota's named keeper, the mean and the day's degree-days worked in the margin where the arithmetic can be checked by any reader, and the running total carried forward in the same hand. The rota is published a fortnight ahead with named understudies, because a ledger with a silent fortnight in it is a forecast with a hole where its evidence should be — and where a day IS missed, the entry says MISSED in the keeper's hand, the degree-days for that day are left blank, and the running total carries a mark every reader can see, so the prediction that follows knows the size of its own uncertainty. Once a week the crew audits the ledger together: totals re-added from the daily column, discrepancies found and entered as corrections with their dates — never erased, because a ledger that hides its corrections is asking to be believed, and this one is asking to be checked.",
       "The prediction, entered in ink before the event, the record's summit: when the running total enters the range the references give for the event, the crew convenes at the table with the ledger, the base card and the season so far — the warm spells, the cold snap that paid nothing for a week, the missed days marked in the margin. Each member states a predicted date and the reasoning in one sentence — the total's pace, the forecast's next week, the plant's own look on the last round — and the crew's prediction is agreed, written on the predictions page, dated and signed by every member, including anyone whose own date differed, because a crew prediction is a position taken together. From that day the checking round walks daily: seen, not seen, or nearly, entered in the ledger's three words with the walker's initials, and nobody — whatever the total says — announces the event from a window, a photograph or a hope. The plant is checked at the plant.",
       "The grading, done by the plant and recorded without flinching: on the day the round reports SEEN, the ledger is opened at the table and the prediction is graded in the open — days early, days late, or on the date — and the grade is written beside the prediction in the same ink as everything else in the book, with the running total the plant actually used, computed from the ledger's own columns. Then the crew does the analysis this record exists for: where did the arithmetic mislead — a warm spell the references' range did not expect, a base temperature that fits this plant in this yard imperfectly, missed days whose blank the crew must now price honestly — and each finding is entered as a finding, in words, because next season's crew inherits this book, and a graded prediction with its reasoning is worth ten ungraded successes. The tell-back for the grading day is said at the plant itself: 'We said the heat would open this by a date we wrote in ink. The plant has now told us what its calendar actually said. We were out by the number in the book — and the book shows our working, our missed days, our warm spell and our grade, all in the same hand. That is what a forecast is: not being right, but being checkable.'",
       "Closing the season, the ledger handed on as the site's heat memory: the crew writes the season's closing page together — the event, the predicted date, the actual date, the grade, the total the plant used, the warmest and coldest weeks, and the one instruction next season's crew will need most, earned at this table. Where the site keeps more than one season's books, this ledger is shelved with them in date order, because a run of graded predictions across years is the beginning of the site's own local knowledge — the references give ranges for the species, but only this ground's ledgers can say what the sum is HERE, and that sentence, earned over seasons, is the record's real harvest. The closing tell-back is said over the shut book: 'In spring we opened a ledger and promised a plant we would count its heat honestly — same hour, same source, missed days marked, predictions in ink. The plant kept its side: it opened when its sum arrived. We kept ours: the book can be checked by anyone, and our grade is in it unedited. A plant keeps its calendar in heat, not in dates — and now, on this ground, so do we.' The thermometer, the base card and the ledger are stored together where the next season's crew will find the whole watch in one place."],
      "A single-plant version (a small crew or a late start): one named shrub, one prediction, the full discipline — daily entries, ink, the daily round, the grade — because one prediction kept honestly teaches the whole arithmetic.",
      "A two-event version (a returning crew): a second named event on a different plant with its own base card, both predicted from the same ledger, and the closing page compares the two grades — the crew learns which plant its ground understands better, and says so.",
      safety="The ledger's work is arithmetic and walking, and its laws are a walker's laws: the checking round goes in daylight, by the site's agreed paths, in the crew's stated pairs, and nobody crosses fences, walls or a neighbour's boundary to reach a plant whose owner has not agreed the crew may visit it — a plant that cannot be visited lawfully is not this record's plant, however perfect its budburst. Thermometers are read where they hang; a glass thermometer is handled by the adult alone if the site still keeps one, and a broken one ends the day's entries until the adults have dealt with it — the ledger records the gap honestly rather than anyone handling glass and its contents bare-handed. Sun and season are respected as the ledger respects everything: the round is short, hats and water follow the site's ordinary hot-day rules, and a round postponed by lightning or dangerous heat is entered as postponed, in ink, without apology — the plant is not checking whether the crew is brave. Predictions are the record's sport and stay kind: a member whose date was furthest out is never the butt of the grading day, the grade belongs to the crew entire, and the book's language for error is arithmetic — early, late, by how much — never a name.",
      tags=SPRING_SUMMER, copy_free=True, no_elimination=True,
      inclusion="A ledger is a table art, and its honours sit at the table: the keeper of the day — reader of the thermometer or the source, worker of the mean, carrier of the running total — holds the season's evidence in their hand, and the auditor's role at the weekly check, re-adding the columns and hunting the discrepancies, is an office of pure attention that any member can hold at full standing from a chair. The checking round divides its labour honestly: walkers report in the ledger's three words, and a member whose ground is the table rather than the path can hold the round's other end — receiving the report, entering it, initialling it beside the walker's name — with the entry carrying exactly the same weight, because the ledger grades the report's honesty, not the reporter's legs. Arithmetic is done aloud and in the margin by whoever works it, checked by a second hand as a matter of the book's law rather than anyone's ability, and the prediction meeting hears every member's date stated in whatever register they command — speech, writing, a finger on the calendar — each entered in the book in the same ink. Nobody's season depends on never missing a day: the rota has understudies by design, a missed day is a mark in a margin, and the crew that keeps the book is the crew whose names are in it, all of them."),
]
PACK += [
    # ---------------- Outdoor, just teens (outdoor age-13/14 primary 8 -> 9) ----------------
    A("microclimate-map-survey", "Microclimate Map Survey",
      "Teens read temperature, shade and wind at a grid of stations in one place at one hour, and draw the map of its many small climates.",
      ["outdoor"], (13, 14), (6, 18), (45, 60), ["outdoor"],
      ["a grid of stations agreed and marked before the survey hour (eight to twelve stations across one real place — the yard, the garden, the school ground: against the wall, under the tree, on the open stones, in the dip — each numbered on a base sketch the surveyor carries, because a reading without a place is a number looking for its map)", "thermometers enough for the teams, of one kind, read the same way (the survey's honesty is simultaneity and sameness: all stations read inside the same ten minutes, every thermometer shaded from direct sun at the same height, and the method card — height, shade, wait time — written on the map's margin before the first reading)", "the wind and shade kit (a ribbon wand or a handful of grass seed for wind, a simple scale agreed at setup — still, stirring, steady — and the shade call made by the same rule at every station: full sun, edge, or deep shade, judged by the shadow map the hour actually casts)", "the map sheet itself — a large sheet with the place's fixed furniture drawn in advance (walls, trees, paths, water) by the survey's cartographer, left with a blank key for the temperature bands the day will earn, because the map is drawn from the readings, never decorated into them"],
      False, "Walk the ground before you promise the map anything, and choose the stations the way the record demands: the place's honest contrasts — the wall that hoards the afternoon sun, the dip where cold air settles, the tree's deep shade, the open middle that gets everything the sky sends. Number the stations on the base sketch and pace the route each team will walk, because the survey's central discipline is time: every station must be read inside the same short window, or the map compares different hours and calls them different places. Agree the method card now and write it on the map's margin as law — thermometer height, two minutes' settle, shade-the-sensor, wind judged by the ribbon's behaviour on the agreed scale, shade called by the shadow's own edge. Choose the survey hour for contrast, not convenience — a still, bright hour when walls and shade are doing their different work — and accept the record's weather law in advance: a survey rained off is postponed entire, never half-read, because half a map is a whole error. Assign teams their stations so every team reads a mix of sun and shade; a team that only reads the sunny stations will draw the map it expects, and this survey exists to defeat expectations, including its own.",
      ["The framing, at the map table, the base sketch in the middle and the place itself in view: 'One yard holds many climates. Stand against that wall at three o'clock and you are in a warmer country than the dip by the hedge — same hour, same sky, different weather. Gardeners know it, lizards know it, and by the end of this hour this crew will have it on paper: a map of the small climates inside one place, read at a grid of stations inside one ten-minute window, every thermometer used the same way, every call made by the same rules. The map is the argument. We are not drawing what we believe — the wall is not allowed to be warm on our map because we feel warm looking at it. It will be warm if its station's number says so, read in shade, at the agreed height, inside the window. And where the numbers surprise us — a cold pocket where we promised warmth, a sheltered corner warmer than the open stones — the surprise goes on the map entire, because a survey that only confirms its crew is a portrait, not a survey.' Stations are issued, the method card is read aloud once, and the teams walk their routes at rehearsal pace before the window opens.",
       "The window, the survey's ten honest minutes: at the keeper's call the teams move to their first stations and the settling begins — thermometers placed by the method card, the two minutes counted without fidgeting, because a sensor lifted early reads the hand that held it, not the place it stands in. Each station is read entire before the team moves: temperature to the agreed precision, wind on the ribbon scale, shade by the shadow's edge, and anything the method card did not predict — the tap dripping at station four, the ants boiling out of station seven's stones — entered in the station's margin, because a map's margins are where its next questions live. Readings are called back to the map table by runner or by the team's return at the window's close, and the keeper enters each number on the station's cell in the hearing of the team that took it — entered as read, never rounded toward the map anyone expected, and a reading a team distrusts is re-taken inside the window by the method, or marked as doubted in the margin, in the open.",
       "The drawing, where numbers become a country: with all stations in, the crew bands the temperatures together at the table — the day's own range divided into the key's bands by the numbers the window actually returned, not by a key copied from a book — and the cartographer colours or hatches each station's ground by its band, the wind calls drawn as arrows of the agreed weight, the shade calls as the shadow's true outline at the survey hour. Then the map is read as an argument, aloud, station by station: where is this place warmest at this hour, and what stands there — a wall, a stone, a south face? Where is it coldest, and what makes it so — the dip, the hedge's shade, the wind's corridor between the buildings? Every claim in the reading must point at a station's numbers; a claim that cannot is struck from the map's conclusions and entered, kindly, in the margin as a belief the survey did not test. The finished map is dated, houred, and weather-noted on its face, because a microclimate map without its hour is a rumour about a place.",
       "The planting test, the map put to work before it is filed: the crew takes the finished map back onto the ground with one practical question the site actually has — where should the tender seedlings harden off, where does the frost settle first, where would a bench be warmest for the winter readers or a water butt slowest to freeze — and the map's answer is walked to and checked at the stations it names, in the open, with the thermometers if the hour still holds. A map that sends its crew to the wrong corner is graded as honestly as any forecast: the stations are re-read, the method re-examined, and the correction entered on the map's margin with its date, because this survey's maps are working documents, not wall art. Where the site's gardeners or groundskeepers will use the map, the crew presents it standing at the place itself — conclusions first, numbers behind every conclusion, surprises named with the same pride as confirmations — and the map's limits are stated by its own makers: one hour, one day's weather, one season, and the invitation to survey again when any of the three has changed.",
       "Closing the survey, the map filed as the place's first climate record: the crew writes the survey's closing note on the map's back — the window, the method card's terms, the warmest and coldest stations with their numbers, the surprise the map is proudest of, and the one instruction the next survey crew will need most, earned on this ground. The tell-back is said over the finished map, the real place visible beyond it: 'An hour ago this was one yard with one weather. It is twelve stations now, and at least three countries: the wall's warm shelf, the open stones' honest middle, and the dip where the cold collects like water. We read them in the same ten minutes, by the same rules, and we drew what the numbers said — including the corner that refused to be what we expected. One yard holds many climates. This map is how we know — and anyone who doubts it can take the thermometers and check our stations, which is exactly what it is for.' The map, the station sketch, the method card and the raw station sheets are filed together where the next survey — another hour, another season — will find the whole watch in one place, ready to be argued with by evidence."],
      "A four-station version (a small crew or a short hour): the place's four strongest contrasts read with the full discipline — same window, same method, the map drawn and read entire — because four honest stations defeat one vague impression of a whole yard.",
      "A two-season version (a returning crew): the identical stations, method and hour surveyed again in the opposite season, the two maps pinned together, and every station's change entered as a finding — the place's climates have biographies, and this crew has read two chapters.",
      safety="The survey's ground is walked before it is surveyed, and its laws are the site's own walking laws: stations are placed only where the crew may lawfully and safely stand — no station inside a works area, a car park's moving lanes, a neighbour's boundary or a patch of ground whose hazard the adults have not cleared — and a station that cannot be stood at safely is moved and the move entered on the sketch, never improvised at the window. Thermometers are carried point-safe and read at arm's length; a glass thermometer, where the site still keeps one, is the adult's instrument alone, and a breakage ends that team's window — the station is marked unread and the reason entered, because the method outranks the completeness of any single map. Sun is the survey's subject and its hazard at once: the window is short by design, hats and water follow the site's hot-day rules, teams rotate through shade between stations where the route allows, and the keeper may call the window closed early for heat, lightning or a turn in the weather — a shortened window is entered on the map's face as its true condition, never silently completed from memory. Ribbons, sketches and loose sheets are kept out of water butts, drains and planting beds, and every marker the crew sets out is counted back in by name at the close.",
      tags=SUMMER, copy_free=True, no_elimination=True,
      inclusion="The survey staffs every kind of attention at full standing: the keeper at the map table — caller of the window, receiver of the readings, enterer of every number in the hearing of its team — runs the survey's clock and its truth from the place's most comfortable seat, and the cartographer's office, drawing bands and arrows from the returned numbers, is table work whose decisions shape the whole map. Stations are assigned by the ground each member can honestly work: the route is planned step-free where the place allows, a station on rough ground can be read by a partnered team whose reader stands where the footing is sure and calls the reading to a recorder at the path — the number carries the same ink either way, because the method governs the reading, not the reader's route. Readings are called aloud and entered twice-checked as the survey's law, judgements of wind and shade are made by the agreed scales rather than by anyone's eyesight alone, and the map-reading at the table hears every team's margin notes in whatever register they were kept — spoken, written, or pointed out on the sketch — each conclusion tested against the same stations. Nobody's survey depends on covering the whole grid: the grid is covered by the crew, and the crew is everybody in it."),
]
PACK += [
    # ---------------- PE & movement, just teens (pe-movement age-13/14 primary 8 -> 9) ----------------
    A("kin-ball-first-session", "Kin-Ball First Session",
      "A three-team game played with one enormous ball: serve by calling a colour, keep the ball off your ground, and win by being hardest to catch out.",
      ["pe-movement"], (13, 14), (12, 24), (45, 60), ["indoor", "outdoor"],
      ["one kin-ball — a very large, very light inflatable ball, a metre or more across, of the kind a whole team can hold up between them (the ball is the game's whole character: it floats, it drifts, it forgives — a substitute must be genuinely big and genuinely light, or the session teaches a different game and says so on the slate)", "three team colours worn unmistakably (bands, bibs or sashes in the three colours the serve will name — the call is the game's engine, so the colours must be readable across the whole court at a glance, in the light the court actually has)", "the court markings — one shared playing square, generous, with no goals, no zones and no centre line to defend (the emptiness is deliberate: with three teams and one floating ball, territory is wherever the ball is falling, and the lines that matter are the court's edges, taped bright and walked at setup)", "the session slate and chalk (teams by colour, the laws taught, faults by kind, and the standings kept as the game itself keeps them — a team's score is the faults it has NOT committed, read aloud at every break so the room always knows who is hardest to catch out)"],
      False, "Inflate the ball before you brief the players, and learn its weather yourself: a kin-ball under-inflated sags and dies, over-inflated skitters off forearms, and the session's first ten minutes belong to the ball's behaviour — how it floats off a flat palm lift, how it drifts on a hall's air currents, how much warning its size gives a receiving team. Walk the court for the game's real hazards, which are not collisions with the ball — the ball hurts nobody — but collisions between players watching the sky: clear the edges, pad or rule out anything a back-pedalling player could meet without looking, and set the rest benches well outside the square. Form the three teams mixed and balanced by the evidence of the handling round, announced from the slate by colour, because the game's strange diplomacy — two teams can tacitly hunt the third — only stays sporting when no colour begins the session outclassed. Set the session's shape now and write it on the slate: handling first, the serve and its call second, fault law third, open play last, because a game whose scoring is other teams' mistakes cannot be learned by players still guessing what a fault is.",
      ["The framing, the great ball resting on the floor between the three teams: 'Three teams, one ball, no owner. This ball belongs to nobody — it is too big to own and too light to fight over. Play works like this: a team in possession serves by striking the ball up and CALLING a colour before it leaves their hands — Omnikin, and the colour named must catch or return it before it touches the ground. If the named team lets it fall, or faults in the handling, the fault is theirs — and BOTH other teams gain. Nobody attacks a goal. Nobody guards a player. You win by being the team the ball cannot catch out, while two other teams take turns trying to catch you. That makes this the most diplomatic game on the shelf: sometimes the bravest play is a gentle serve at the strongest team, sometimes the whole court senses whose turn it is to fall — and the slate keeps the only score that matters, the faults, in chalk, where diplomacy can see itself. We learn the lift first, the call second, and only then do we hunt.' The serve is demonstrated entire — lift, call, flight, catch — by a rehearsed trio before any law is argued, because this game is understood by the eyes ten minutes before it is understood by the ears.",
       "Handling school, where the game's real skill is taught: the ball is received on forearms and open palms and lifted, never punched — a punch sends it anywhere, a lift sends it where the team agrees. Teams practise the three-player lift in their colours: two support, one strikes upward, the ball climbing straight and true, and the keeper calls the fault honestly in practice — a ball struck downward, a ball caught and held rather than lifted, a ball allowed to roll off a shoulder untouched. The call is rehearsed as a skill in itself: the striker names the colour loud and early, before contact, because a late call is a trap and the law will treat it as one — the named team must have the ball's whole flight to organise, and a serve that ambushes by silence is chalked as the server's fault, not the receivers' failure. Every player serves, lifts and receives in school, in rotation, because a colour with one server is a colour with a single point of failure, and this session is building teams, not specialists.",
       "First play, in short rounds the slate governs: possession rotates by the fault law entire — a team that faults yields the serve; a serve whose called team returns the ball cleanly puts the ball live for the return call, and the game flows serve to serve with the keeper chalking faults by kind: ground, hold, late call, out of court. Early rounds are stopped kindly and often: a team milling in confusion is re-formed into its receiving shape — spread, knees soft, eyes up, the lift rehearsed as one word — and the correction is chalked as teaching, never as shame, because three-team play bewilders every first room and the bewilderment is the curriculum. The keeper names the diplomacy when it first appears, aloud and with respect: the two stronger colours beginning to serve only at the third is legal, visible, and answerable — the hunted team's counter is not complaint but cleanliness, lifting everything, faulting at nothing, until hunting them stops paying.",
       "The standings round, when the laws are holding and only then: rounds lengthen, substitutions rotate by the slate's published order so every player defends and serves inside the session's real pressure, and the keeper reads the fault standings aloud at every break — the game's scoreboard is a list of mistakes, which makes reading it an education in itself: the leading team is the one with least chalk against its colour. A runaway session is rebalanced once, in the open, by the keeper's stated evidence — teams re-dealt by colour if the fault columns have made the game's diplomacy a procession — because a session where the hunted team never receives a fair serve teaches the hunters nothing either. Between rounds the ball rests and arms rest with it: lifting a metre of floating ball is shoulder work disguised as play, and the session's pace is set by the slate before enthusiasm can spend the room's best handling in the first rounds and call the rest heart.",
       "Closing, the slate read entire and the great ball deflated by its crew: the keeper reads the session aloud — laws taught, rounds played, faults by kind and by colour, and the session's final standings spoken the game's way: the colour hardest to catch out, named with its fault count entire. The room agrees its one number to beat: the longest unbroken rally of serves and returns the whole court held without a fault, counted honestly whether it is four or fourteen. The tell-back is said with the ball resting against the slate: 'An hour ago, three teams and one floating ball sounded like a party trick. Now this room lifts together, calls early and loud, hunts in the open and answers a hunt with clean hands. Three teams, one ball, no owner — and the winners are simply the team the ball could not catch out. Next session the rally mark is waiting, and the ball will be inflated before we are.' The ball is inspected as it is folded — seams, valve, slow leaks listened for — faults noted to the adults, and ball, colours and slate are stored together where the next session will find the whole game in one place."],
      "A two-team version (a small group or a first hall): the same lift, call and fault law played colour against colour with the serve alternating — the diplomacy goes quiet, the handling school entire, and the session's rally mark still honestly kept.",
      "A seated-circle version (a court whose space is tight): teams in a wide circle lift the ball across and down to the called colour's sector, ground faults judged where the ball lands — the call, the lift and the slate entire, at a scale where control outranks flight.",
      safety="The ball is this game's mercy and its hazard is everything else: a kin-ball cannot injure, but players watching it can back into walls, benches and each other, so the court's edges are cleared and padded at setup, the square is walked before play, and a player who must look down stops being a receiver until their footing is sure — the keeper calls 'eyes down' balls dead without blame, always, because no fault on the slate is worth a fall. Receiving is taught before it is tested: lifts come from forearms and open palms at chest height or above, nobody heads this ball — it is light enough to invite it and drifting enough to punish it — and a ball falling onto a player who has lost it in the light is a ball let fall, chalked and replayed, never rescued through a face. Inflation is the adult's or keeper's checked job: an over-hard ball is deflated to the session's agreed give before play, and a ball that bursts or tears mid-round stops play at once — the square is cleared of its skin before feet return to it. The call law is a safety law in disguise: serves are never aimed at a team still re-forming, a late call is the server's fault entire, and a team that needs a breath asks the keeper for a held serve and gets it without negotiation — three teams can wait; one winded player should never have to chase a floating ball to earn a rest.",
      copy_free=True, no_elimination=True,
      inclusion="Three-team play staffs its honours by colour, and the session says so in the open: the keeper — caller of rounds, judge of faults, holder of the slate — runs the game from the court's side at full authority, and the standings they read are the game's memory. Receiving shapes are built so every player's ground is real: a receiver may hold a marked sector from a seated or standing base agreed with the keeper, because the skill honoured is the lift — forearms, timing, the ball sent up true — not the run that preceded it, and a sector held cleanly is a sector the called serves must respect entire. The serve rotation is the slate's, published, so quiet players serve inside the game's real pressure on their turn rather than by shouting over louder colours, and the handling school gives every player as many rehearsed lifts as they want before open play, with the ball's float making first success genuinely likely — this game's mercy is that its ball wants to be caught. A member whose day is the slate, the colours and the rally count is inside the game's honours, not beside them: the framing said the winners are the team the ball cannot catch out, and the slate is where being caught out is written down — the keeper's chalk is the game's official truth."),
    # ---------------- Music & rhythm, just teens (music-rhythm age-13/14 primary 8 -> 9) ----------------
    A("conducting-patterns-studio", "Conducting Patterns Studio",
      "Teens learn to lead music with their hands: beat patterns in two, three and four, clear cueing, and a room that starts and stops together.",
      ["music-rhythm"], (13, 14), (6, 24), (45, 60), ["indoor"],
      ["a beat the whole room can make together before anyone conducts it (voices on a counted syllable, hands on knees, or whatever instruments the room truly has — the studio's orchestra is the room itself, assembled and tested before the first pattern is drawn, because a conductor rehearsing with an ensemble that cannot yet sound together is conducting the air)", "the pattern cards — the beat shapes for two, three and four drawn large, one per card: down-and-up, the triangle, the square every beginner's book teaches (the cards stay visible all session, pinned where every conductor can glance at them, because this studio teaches reading a pattern while leading, not memorising under pressure)", "a baton or its honest substitute for every conductor who wants one (a pencil, a chopstick, a short dowel — the studio states plainly that the hand alone conducts perfectly well and the stick only makes the hand's writing larger; nobody's authority waits on equipment)", "the studio log, one page per conductor (patterns led, tempos chosen, the ensemble's verdicts on clarity entered in the same ink — kept by the session's keeper, because a conductor's craft improves on written evidence: where the room entered ragged, where the cut-off landed clean, and what the hands did differently)"],
      False, "Assemble the orchestra before you teach a single pattern: the room agrees its sound — one strong syllable counted aloud, hands on knees, shakers if the room truly has them — and rehearses starting and stopping on a raised hand until the room can do both as one body, because that shared discipline is the ground every conductor in this studio will stand on. Fix the studio's law at setup and write it on the log's first page: the conductor's hands are the only signal, nobody plays early to be kind, nobody plays past a cut-off to be funny, and the ensemble's loyalty is to the pattern, not to rescuing a conductor whose beat has wandered — a room that covers for its conductor teaches them nothing, and this studio's kindness is honesty at teaching tempo. Set the session's shape now: patterns first at walking pace, cueing second, a full conducted piece last, with tempos agreed before each turn — a conductor chooses a tempo they can keep, states it, and is judged on the room's togetherness, never on speed. Choose the first conductors by the log's rotation, open to every member in turn, because the podium in this studio is a rota, not a throne.",
      ["The framing, the pattern cards pinned, the room silent and watching one raised hand: 'Your hands speak first; the room answers. A conductor makes no sound at all — and yet the whole room's sound is theirs: when it starts, how fast it breathes, who enters, and the exact silence it ends in. That is not magic and it is not rank. It is a written language of four shapes, and today this room learns to write it and to read it. The patterns are on the cards: two, a down and an up; three, a triangle; four, a square with the downbeat at the floor, where every bar comes home. A clear beat is a promise the room can keep. A vague one is a rumour the room must guess at — and musicians should never have to guess at the person leading them. So we will conduct slowly, we will cue like we mean it, we will cut off clean and count the silence as music, and the log will record what the room actually did under each pair of hands — entered together or ragged, stopped clean or trailing — because that record, not applause, is how a conductor improves.' The leader conducts one bar of four at walking pace, the room answers on the syllable, the cut-off lands — and the silence after it is held a full breath before anyone speaks, so the room hears what a clean ending sounds like.",
       "Pattern school, every hand learning the shapes before any hand leads the room: conductors trace the cards in the air at teaching pace — downbeat falling like a dropped ball, the rebound small and honest, the pattern's corners distinct rather than stirred — first in unison led by the keeper, then in pairs, each partner reading the other's pattern aloud by its numbers while it is being drawn, because a pattern you can read is a pattern you can lead. The studio names the beginner's three betrayals and rehearses against each: the downbeat that floats (fixed by letting the wrist drop, not push), the pattern that shrinks as tempo rises (fixed by conducting the first bar of every turn at full size), and the beat that hurries when the conductor gets excited (fixed by the oldest law in the craft: the room follows the hands, so the hands must be calmer than the music feels). Tempos are set by a spoken count before the pattern starts — the conductor gives the room its pulse in words first, then takes it into the hands, and the handover is practised until it is seamless, because a room that starts guessing has usually been handed a pulse that changed at the handover.",
       "Cueing and the conducted piece, the studio's working middle: conductors learn the cue as a sentence with three parts — look at the section, lift with the breath, land the entry on the beat the section was promised — and the room practises entries by halves, one side entering on its cue over the other's held syllable, ragged entries re-run once without blame and entered in the log by their cause: cue late, cue small, cue aimed at nobody. Then the studio builds its piece from the room's own sound: a short counted structure the keeper writes on the board — sections entering and leaving by cue, one tempo change led deliberately and signalled a full bar early, a held silence counted in the pattern, and a final cut-off the whole room has rehearsed. Each conductor leads the piece entire in rotation, the ensemble plays the law — no covering, no early kindness — and after each turn the room gives its verdict in the log's own terms: where it entered together, where it guessed, and the one thing the hands could change, stated by the conductor first, because a conductor who can name their own vagueness has already half repaired it.",
       "The verdict round and the return podium, where improvement becomes evidence: after every member has led, the log is read back entire — patterns, tempos, the ragged entries and the clean ones in the same ink — and the studio chooses the turn it will re-run: not the worst, but the conductor whose own stated fix is clearest, because the studio's last lesson is that conducting improves by one named repair at a time. The return conductor leads the piece again with their fix in force, the room plays the law entire, and the difference — entered together where it was ragged, the cut-off clean where it trailed — is entered in the log beside the first attempt, dated, as the session's proof. Conductors sign their pages as the room's leaders for the day, all of them, because in this studio the podium belonged to the rota and the evidence belongs to everyone whose hands and voices made it.",
       "Closing the studio, one bar of silence kept together: the room stands, the final conductor — by the log's rotation, not by acclaim — raises their hands, gives the count, and leads one slow bar of four with the whole room sounding, ending in a cut-off whose silence the room holds for a full four counts before a word is spoken. The keeper reads the log's closing line: turns led, patterns held, the fix that worked. The tell-back is said with the pattern cards still pinned: 'This morning the music in this room had one leader, and it was habit. Now it has a rota. We learned the shapes — down and up, the triangle, the square that comes home to the floor — we cued with a look, a breath and a landing, we stopped clean and counted the silence as music, and the log shows every pair of hands what the room did under them, ragged and clean in the same ink. Your hands speak first; the room answers. They answered — because the promises were clear enough to keep.' The cards are copied into the log before they come down, batons are counted back by their holders, and the log is stored where the next studio will find the whole argument of hands in one place."],
      "A one-pattern version (a short session or a first room): the whole studio inside the four-pattern alone — school, cueing by halves, the conducted piece, the verdict and the return podium — because one pattern led honestly teaches the whole craft's grammar.",
      "A silent-orchestra version (a room that must stay quiet): the ensemble answers with visible rhythm — raised hands, tapped knees under the table's edge, a written count — and every law of pattern, cue and cut-off is kept entire, proving the studio's point that conducting is a visual language first.",
      safety="Volume obeys the studio's standing law, set by the adult at the framing and entered in the log: the ensemble's working sound is a teaching volume — a counted syllable and hands, not a shout — and any run that has to be conducted through raised voices is stopped and reset quieter as a craft correction, because a conductor who cannot be seen must not be replaced by a room that yells. the law is stated plainly in the log: if ears are ringing, the room was too loud — any member may say so and be thanked, since hearing is every musician's first instrument. Batons and their substitutes are hands' tools and obey a tool law: points travel down when walking, no baton is ever flourished at a face, and a dropped baton is retrieved between turns, never dived for mid-pattern. Space is a conducting hazard nobody expects: conductors stand with a clear arm's circle around them, the ensemble's first row sits beyond a full pattern's reach, and tempo games that invite wild arm-waving are this studio's named exclusion — the patterns stay their card sizes at every tempo, which is simultaneously the craft's rule and the court's safety. Song and syllable content follows the room's standing rule: words are the adult's to clear in advance, and a member who will not sound a syllable on conscience or comfort keeps the log or conducts at full standing, without explanation owed.",
      copy_free=True, no_elimination=True,
      inclusion="The podium is the most accessible office in music, and this studio is built to prove it: conducting is done standing, seated, or from wherever the conductor's hands are most readable — the pattern's authority is its clarity, not its height — and the ensemble is arranged in a shallow arc at setup so every seat can see every conductor without turning. A conductor may lead with both hands, one hand, a baton, or a head-nod pattern agreed with the keeper and drawn on their card, because the language being taught is intention made visible, and it has dialects. The keeper's chair — log, rotation, verdicts in the same ink — is seated work at the studio's centre, and the ensemble's parts divide by honest capacity: a member may hold the counted syllable, a knee-drum pulse, a shaker line, or the silence-count at the held bar, each a real part the conducted piece cannot do without, each credited in the log. Tempos are chosen by each conductor for the room they actually face, stated in advance and never sprung, patterns are traced at teaching pace for as many rehearsals as a conductor wants before their turn, and nobody auditions for the rota: the log's order is the only qualification, and the verdict language — together, ragged, guessed — describes the room's evidence, never the conductor's worth."),
]
PACK += [
    # ---------------- Rainy day, just teens (rainy-day age-13/14 primary 8 -> 9) ----------------
    A("one-table-micro-museum", "One-Table Micro Museum",
      "On a rainy day, teen curators build a real museum on one table: objects on loan from their owners, honest labels, and one argument made of things.",
      ["rainy-day"], (13, 14), (6, 18), (50, 60), ["indoor"],
      ["one table that is the museum entire — its edges are the gallery walls, agreed and cleared before a single object is invited (the museum's discipline is scale: everything must earn its place on one table, and the choosing, not the size, is the curators' craft)", "objects on loan from their owners in the room — everyday things with real histories, invited under the loan law stated at setup: nothing fragile beyond rescue, nothing irreplaceable, nothing its owner cannot watch a stranger read a label beside, and every loan entered in the register with its owner's name and its return condition", "labels written the museum's way — card stock and the curators' best hand: the object's name as its owner names it, one line of fact, one line of the owner's own words where they grant them (a label is a promise: every word on it must be checkable with the owner standing in the room)", "the museum register and the gallery plan (a sketch of the table divided into the exhibition's sections before objects are placed, and the register afterwards: loans in, loans out, every object returned entire and the return signed — the register is the museum's conscience and outlives the exhibition by design)"],
      False, "Issue the invitation before you clear the table, and issue it under the loan law entire: curators ask owners — including themselves — for objects that carry a true story small enough to stand on a table: the ticket stub, the repaired mug, the key to a door that no longer exists. Refusals are complete answers and are never argued with; the register has a column for declined loans, entered without a reason, because a museum built on pressure is a confiscation with labels. Agree the exhibition's argument at setup, in one sentence the whole crew can say: what is this table claiming about the things people keep? Every section of the gallery plan must serve that sentence, and an object that serves no section — however beloved — waits for another exhibition, which is the hardest sentence in curation and the one this record exists to teach. Set the handling law now and write it on the register's first page: objects are moved by their owners or not at all; curators point, describe and arrange by invitation; labels are drafted, shown to the owner, and corrected in the owner's hearing before they stand. The museum opens when the plan, the register and the labels agree — and not a minute before.",
      ["The framing, around the empty table, the register open and the plan sketched: 'A museum is an argument made of objects. Not a shelf of nice things — an argument. This table will claim something before the hour is out: that the things in our pockets and our kitchen drawers are evidence — of journeys, of repairs, of people who are not in this room. Our evidence is on loan, and loans have laws. Nothing here was taken. Everything here can be checked — its owner is standing in this room, and every label we write will be read by that owner before a single visitor sees it. We will choose like curators, which means we will leave good objects out — not because they failed, but because the argument is one table long. And when we close, every object goes home entire, signed out of the register by the hand that signed it in. A museum you can trust is a museum that gives everything back.' The argument sentence is read aloud, the plan's sections are named, and the first loans are invited by name, in the open, under the law.",
       "The labels, written under their owners' eyes, the exhibition's scholarly middle: each object's label is drafted by its section's curator and checked against the museum's standard — name as the owner names it, one line of fact that can be verified in the room, one line of the owner's words, quoted only with permission and corrected until the owner calls it true. Facts are hunted honestly: a date the owner is unsure of is written as the owner gives it — 'kept since about 2019' is a better label than a confident invention — and any claim the room cannot check is struck or attributed, because a museum label is the strongest sentence in this record and it is not allowed to be a guess wearing a card's clothing. Arrangement follows the labels, never precedes them: owners place their own objects in the sections the plan assigns, curators direct by word and pointing hand, sightlines are walked from a visitor's height, and crowded sections are pruned by the argument's law — the object that serves the sentence least returns to its owner with the curators' thanks and its register entry marked 'not exhibited', which is an honourable line and reads as one.",
       "The opening, run like the small serious thing it is: a curator states the argument at the table's end, tours are given in small groups at a visitor's pace, and questions are answered from the labels and the register — a question neither can answer is answered honestly as unrecorded, and the asker is thanked, because 'the museum does not know' is a sentence real museums say and this one will learn to say it without shame. Owners may stand by their objects or walk the exhibition as visitors, as they choose; a visitor who disputes a label takes the dispute to the register table, where the owner is the appeal court and the label is corrected on the spot in the owner's words, with the correction initialled — the exhibition improves in public, which the framing promised it would. Handling stays by the law entire throughout the opening: visitors look with their eyes, owners alone move objects, and a curator who sees a reaching hand intervenes kindly and early, offering the owner's own demonstration instead.",
       "The closing and the great return, the register's finest hour: the exhibition is declared closed by the argument's own curator, the argument sentence is read once more over the full table — and the crew hears, together, whether the objects made it — and then the return begins in register order: each object lifted by its owner, checked against its entry, signed out in the same hand that signed it in, until the table stands empty and the register balances to zero outstanding. Objects marked 'not exhibited' are thanked by name in the closing, because an exhibition is also the loans it declined to use, and their owners lent in good faith entire. The labels of exhibited objects are offered to their owners first; labels declined are filed with the register, because next exhibition's curators inherit this one's standards in its own handwriting.",
       "Closing the museum, the table wiped and the register shelved: the crew writes the exhibition's closing page in the register — the argument, the objects exhibited, the corrections made in public, the loans declined and not exhibited, and the one instruction the next curators will need most, earned at this table. The tell-back is said over the empty table, which is the exhibition's last exhibit: 'An hour ago this was a table. Then it was a museum: one argument, made of other people's kept things, every label checked by the person it described, every object home again by signature. The table is empty now and the register balances — and that emptiness, signed for, is the most professional object we made all day. A museum is an argument made of objects. Ours held — and everything it borrowed, it returned.' The register, the plan and the filed labels are stored together where the next exhibition will find the whole museum in one place."],
      "A pockets-only version (a short hour or a shy room): every object comes from what the room is already carrying — keys, stubs, stones, folded notes described but never unfolded — the loan law, labels and register entire at the smallest honest scale.",
      "A one-section version (a returning crew): the table argues a single theme — repair, journeys, gifts never used — with loans invited against the theme in advance, and the closing page compares this exhibition's discipline with the register's last.",
      safety="The loan law is this record's safety system and it is absolute: nothing irreplaceable, fragile beyond rescue, sharp, hot, edible, alive, or of real monetary or sentimental value beyond recovery is ever invited, and the adults hold a veto they may use without explanation — an object declined by the veto is entered as declined, full stop, and its owner is thanked in the same breath. Nothing is ever taken, borrowed by surprise, or moved by a non-owner: an object whose owner steps out is an object frozen in place until they return, and the register notes the freeze without drama. Personal objects can carry private facts, and the museum treats privacy as a handling hazard: labels show only what owners approve, photographs of the exhibition are taken only with every owner's consent for their own objects — never by default — and an owner may withdraw an object and its label at any moment, mid-opening included, without giving a reason, the register recording the withdrawal as a right exercised, never as an incident. Cleaning follows the owners' instructions or does not happen: curators' hands are clean and dry before the opening by the room's ordinary law, food and drink never share the museum's room-side of the table, and spills end the opening until the register's crew has accounted for every object in the wet zone.",
      copy_free=True, no_elimination=True,
      inclusion="Curation is seated, scholarly work, and its offices are this record's honours: the registrar — keeper of the loans, the signatures and the balancing zero — runs the museum's conscience from a chair at the table's end, and the label-writers' craft is judgement and a good hand or a dictation taken verbatim, either carrying the same authority, because a label is true or it is not, in anyone's handwriting. Owners place their own objects by the record's law, which means the arrangement is built from as many kinds of movement as the room contains, directed by curators whose pointing, describing and sketching the plan are full curatorial acts — the plan's hand and the placing hand are equal offices and the register credits both. Tours are given at a visitor's pace in small groups, questions can be written on cards and read aloud by the tour's keeper, and an owner may answer for their object in speech, in writing on the label's back, or not at all beyond the approved label — silence beside one's own object is a complete curatorial position. Nobody's exhibition depends on lending: a member who lends nothing and curates everything has held the museum up entire, and the closing says so."),
    # ---------------- Crafts, just teens (crafts age-13/14 primary 9 -> 10) ----------------
    A("sashiko-stitch-sampler-studio", "Sashiko Stitch Sampler Studio",
      "Teens learn sashiko's running stitch — counted rows of small, even stitches through cloth — and build a sampler of traditional geometric patterns.",
      ["crafts"], (13, 14), (4, 16), (50, 60), ["indoor"],
      ["cloth that takes a needle kindly — plain-weave cotton in a deep colour, cut in sampler squares before the session (indigo is traditional because the white thread shows on it like surf, and the studio says so honestly: the pattern must be visible to be judged, so the cloth is chosen for contrast, not fashion)", "white sashiko-style thread and long sashiko needles, with thimbles of the palm kind the craft actually uses (the studio's tools are the craft's own: a long needle carrying many stitches at once, a palm thimble pushing it — substitutes are named as substitutes on the sampler card, never passed off as the real kit)", "the pattern cards — the traditional geometric patterns drawn on dot grids: seigaiha waves, asanoha stars, the simple straight-row grounds (each card names its pattern, shows its grid, and states its counting rule, because these patterns are mathematics that happens to be thread — the grid is drawn, the stitches are counted onto it, and a pattern error is findable, crossing by crossing)", "marking tools the cloth forgives — chalk pencils or water-erasable markers and rulers for the dot grids (marks are scaffolding, not the building: they wash or brush away, and the sampler's honesty is that its grids were drawn before they were stitched, which the card states as method, never hides as shame)"],
      False, "Prepare the cloth before you promise the pattern anything: squares cut true, edges finished against fraying by the adults or the studio's experienced hands, one practice scrap per member set out with the samplers, because the first inch of running stitch anybody sews belongs on scrap, not on the record. Draw the session's shape on the board now and keep it: the stitch first — loaded, rocked, even — the grid second, one traditional pattern third, because sashiko punishes the hurried in a specific way: uneven stitches cannot be hurried even, and a session that begins with the pattern teaches pattern-copying, while a session that begins with the stitch teaches the craft. Agree the studio's standard before a needle is threaded and write it on the sampler card: stitches small, even, and counted — the same length on the cloth's face as the gap between them, as near as the hand can honestly keep — and unpicking is a normal tool of the craft, used without comment, because a row re-sewn teaches the hand what a row endured does not. Credit the tradition by name at setup: this is a Japanese craft, centuries old, born of mending and warmth, learned here as beginners from its published patterns — the studio's respect is in its accuracy about what it is doing and whose it is.",
      ["The framing, cloth squares down, one finished sampler where the room can see it: 'Small stitches, counted rows, no loose ends. Sashiko began as work — stitching layers of cloth together to make them warmer and stronger, mending a jacket until the mending itself became the decoration. Its stitch could hardly be simpler: in, out, in, out, a running stitch a child can learn in a minute. Its discipline is everything else. The needle carries many stitches before it pulls through. The stitches sit small and even, the same on the face as the spaces between them, row after counted row, until the geometry stands up off the cloth — waves, stars, fields — drawn in nothing but patience and arithmetic. Today nobody here finishes a jacket. Everybody here starts a sampler: the stitch learned on scrap until it runs even, a grid drawn true, one traditional pattern counted onto it stitch by stitch — and a row that wanders gets unpicked, kindly, by its own maker, because the sampler is where this craft keeps its standards, and its first standard is that the hand tells the truth.' The finished sampler is passed hand to hand — its back shown as freely as its face, because in this craft the back is evidence too — and the practice scraps come out.",
       "Stitch school, the craft's whole foundation, taken at teaching pace: members learn the loading — stitches gathered along the long needle, four, six, more as the hand learns, the palm thimble pushing the needle's eye through in one rocking motion — first on scrap, in straight lines, the keeper walking the table reading stitches the way the card defines them: length, gap, the rhythm of the two. Unevenness is read in the open and kindly: stitches that lengthen as the row runs mean the loading is greedy, stitches that shrink mean the hand is hurrying the pull — each fault has its repair, and the repairs are taught as the craft's real content, because a stitch that only works slowly and supervised is not yet learned. When a member's scrap shows a hand's length of honest running — even, counted, the back as tidy as the face — they graduate to their sampler square in the studio's small ceremony: their scrap is initialled and pinned to the board, the board of first rows, where it stays all session as the room's evidence that every pattern on every square began as exactly this.",
       "The grid and the pattern, mathematics laid on cloth: each member chooses one traditional pattern from the cards — the waves, the star, the straight grounds — and draws its dot grid on their square by the card's counting rule, ruler true, marks light, the grid checked by a partner against the card before a stitch is sewn, because a grid error sewn over is a pattern error with an alibi. Stitching follows the grid in the pattern's stated order, rows counted aloud in the early going if a member wants the count spoken, the needle loaded, rocked, pulled — and the studio's working silence is a real material here: talk in waves between rows, quiet inside them, because counted work and conversation are both good and they take turns in this room by agreement. A member who finds their pattern wandering does the craft's honest thing in the craft's own order: stop, find the first wrong stitch by counting back against the grid, unpick to it, re-sew — and the keeper notes re-sewn rows on the sampler card as the craft counts them: not as failures, but as the rows the maker refused to let stand, which in sashiko is a definition of quality.",
       "The finishing, where a sampler becomes a record: edges are checked and made good, marking lines are brushed or washed away by the method the markers promised, and each sampler is read at the table entire — pattern named, rows counted, the maker's own verdict stated first in the card's terms: where the stitch runs truest, where it still wanders, and the one repair the next session would make. Samplers are signed on their backs in running stitch or in the keeper's hand at the maker's dictation, dated, and their cards completed — pattern, grid, rows re-sewn, the maker's verdict — because this studio's samplers are a pattern library the room is building for itself: next session's beginners will learn the waves from these squares, faults and all, and a library whose books hide their repairs teaches nothing. The board of first rows comes down last, scraps returned to their makers or filed with the samplers by the makers' choice, each one the session's true first exhibit.",
       "Closing the studio, the samplers held up together: the keeper reads the studio's record aloud — patterns attempted in the tradition's own names, rows sewn, rows re-sewn and why that count is read with pride, and the room's one shared measure: the longest run of even stitching any hand held without a wander, claimed only where the sampler shows it. The tell-back is said with the finished squares raised, indigo and white in the room's light: 'This morning these squares were plain cloth and a borrowed tradition. Now they carry waves and stars in counted white rows — every stitch small enough to be honest, every grid drawn before it was sewn, every wandering row unpicked by the hand that sewed it and sewn again true. Small stitches, counted rows, no loose ends. The tradition kept its side for some centuries; today, on these squares, so did we.' Needles are counted back by name into their cushion, thimbles and thread are gathered by their keepers, and the samplers and cards are stored flat together where the next studio will find the whole library in one place."],
      "A straight-rows version (a first studio or a short hour): the whole discipline on the ground pattern alone — stitch school entire, one square of counted straight rows in bands of widening and narrowing spacing — because the ground every pattern stands on is a fit first sampler entire.",
      "A mending version (a returning studio): the stitch turned to its first purpose — a worn patch of the member's own clothing reinforced in counted rows, the owner's consent and the garment's story stated on the card — the sampler's standards applied to a repair that will actually be worn.",
      safety="Needles are this studio's law and they are governed like the tools they are: every needle is counted out by name at setup and counted back by name at the close, a needle not in cloth, in a hand, or in the cushion is a needle the whole room stops to find — nobody leaves, nobody tidies, until it is found — because a lost needle in a room of cloth and cushions is found eventually by somebody's skin, and the studio's count exists so that it is found by eyes instead. Stitching posture is taught as craft and kept as law: work held up toward the light, never sewn down into a lap where the needle's exit is a guess, and the palm thimble is worn for pushing, because sashiko's rocking motion puts real force through the needle's eye and the thimble is the craft's own engineered answer, not an ornament. Scissors and rotary cutters, where the setup used them, are the adults' and experienced hands' tools, closed and shelved before the stitching begins; thread is cut, never bitten, and never left trailing where a chair leg or a foot will find it. Cloth and thread are the room's own clean materials; a pricked finger is cleaned and covered before work resumes by the room's ordinary law, the sampler is set aside until its maker returns to it, and no sampler with any mark on it is ever passed hand to hand — the finished sampler the framing passes round is the studio's clean demonstration piece, kept for exactly that purpose.",
      copy_free=True, no_elimination=True,
      inclusion="Stitch work divides its honours between the hand and the eye, and this studio staffs both at full standing: the grid-checker's office — reading a partner's drawn grid against the pattern card, catching the counting error before it is sewn — is pure judgement, held from any seat at the table, and a square whose grid was checked well carries its checker's initials beside its maker's, because the library being built credits prevention as highly as production. Sewing itself adapts at the table's own furniture: cloth can be held in a frame or hoop where a member's grip prefers it, work is lit by the best light the room can arrange as a matter of setup rather than request, stitches can be counted aloud by a partner for any member who wants the count spoken, and stitch length is judged against the card's gauge, not against a neighbour's smaller hand — the standard is the sampler's own stated measure, the same for every square. A member may dictate their sampler card entire, sign their square in the keeper's hand at their dictation, or hold the studio's other high office — keeper of the needle count, whose out-and-in tally at setup and close is the room's safety made audible. Nobody's craft depends on finishing a pattern inside the hour: a sampler honestly begun, its rows true as far as they run, is a complete exhibit in this studio, and the closing reads it as one."),
]
PACK += [
    # ---------------- Icebreakers, just teens (icebreakers age-13/14 primary 9 -> 10) ----------------
    A("personal-map-introductions", "Personal Map Introductions",
      "New teens draw a map of the places that made them — real, remembered, or hoped for — and introduce themselves by giving the room a tour.",
      ["icebreakers"], (13, 14), (6, 24), (40, 55), ["indoor"],
      ["large plain paper and the drawing kit the room trusts — pencils, colour for those who want it, rulers strictly optional (a personal map is not a test of draughtsmanship: a labelled box with a river through it is a complete country, and the session states that law before a line is drawn, because the map's job is introduction, not cartography)", "the legend cards — the map's agreed symbols, kept deliberately few: a star for where I am known, a road for a journey that changed me, water for where I am calm, a door for a place I mean to reach (members may invent one symbol of their own and must then teach it, because a legend with one personal entry is this record's signature: the room learns each map partly in a shared language and partly in its maker's)", "the tour slate — the session's order of guides, kept by the host: each tour's country, its guide, and its three stations (the slate's law is three: every guide chooses exactly three places to present, so a tour is an introduction, not an autobiography, and every country, however rich, is toured at the same honest length)", "the blank-country law, stated at setup and printed on every legend card: any region of any map may be left blank, unlabelled and unasked-about, by its maker's whole right — no reason, no apology, no tour stop (the law is the record's foundation: a map its maker cannot censor is not an introduction, it is an interrogation with pencils)"],
      False, "Draw the legend before you invite a single map, and draw it where the whole room can keep it in sight: the four shared symbols, each named in the plainest words the room owns, with the session's two laws read aloud as part of the setup itself — every map is its maker's to censor, and every tour is three stations, no more. Choose the paper and the time honestly: a map drawn in four frantic minutes is a doodle with a legend, so the drawing is given the session's longest unbroken stretch and the host protects it like a reading room — music low or none, talk in the pencil register, nobody's country commented on while it is still being made. Set the tour order at setup by the slate's rotation, guides volunteering for early slots if they wish, because a tour is a kindness done at speaking pace and the order should never be a popularity instrument. Prepare the room's reception law with the same care as its drawing law: listeners tour as guests — questions at a tour's end are invitations a guide may accept or pass entire, nobody photographs a map without its maker's written-on-the-slate consent, and every map leaves the room in its maker's hands unless the maker freely gives it to the session's folder.",
      ["The framing, legend cards up, paper still blank: 'Draw the country only you know. Every one of us is from somewhere — not just a town, a whole geography: the kitchen where your name is said the way you like it, the road that taught you something, the water where your head goes quiet, the door you have not walked through yet and mean to. Today each of us draws that country as a map. There is a legend, and it is shared — a star where you are known, a road for the journey that changed you, water for calm, a door for where you are headed — and one symbol that is yours alone, which you will teach us when your tour comes. Then each guide gives the room a tour: three stations, chosen by you, at a speaking pace — an introduction, not an autobiography. And the law that makes all of this safe enough to be honest: any part of your country may stay blank. Unlabelled. Unexplained. Blank is a complete answer on a map, and in this room nobody — nobody — asks what a blank country is hiding. It is not hiding. It is yours.' The legend is read symbol by symbol, one invented-symbol example is drawn by the host on the board — theirs, honestly — and the drawing begins in the session's protected quiet.",
       "The drawing, the session's long protected middle: maps grow at their makers' own geography — some dense as cities, some three places and a river — and the host walks the room as a keeper of conditions rather than a critic: paper for the member whose country outgrew its sheet, time warnings given gently and early, and the blank-country law kept in practice, which means the host's own curiosity is the first thing disciplined — no 'what's that going to be?' over any shoulder, ever. Members who finish early take the legend's second job: drawing the session's shared compass rose for the folder — north invented by the room, since a compass for countries like these points at something better than north — while slower countries are given the session's full grace, because a map hurried at the end is a country with its last county amputated, and the slate's tours can begin around a table where one map is still being drawn if its maker consents to the company.",
       "The tours, three stations each, run from the slate: a guide stands or sits with their map held, pinned or laid as they choose, and walks the room through their three stations in their chosen order — the star, the road, the water, the door, the invented symbol taught when its station comes — at a pace the host guards: a tour is finished when its three stations are given, applause is the room's, and questions follow the reception law entire, accepted or passed without a flicker. Listeners' duty is cartographic, not conversational: each listener notes, on their own tour card, one place from each country they would visit and why in four words or fewer — a discipline that keeps attention on the maps and gives every guide written evidence of having been genuinely toured, which the guides collect at the session's end. A guide may tour a map drawn sparse, drawn fictional-leaning, drawn almost entirely of doors — the slate records the country and its three stations without ranking, because this record's introductions are not entries in a contest of interesting lives.",
       "The atlas round, the session's closing geography: with its makers' consent — consent asked map by map, a no entered on the slate as a complete and respected answer — the maps are laid together on the long table as one atlas of the room, and the crew reads the shared country aloud: the waters are many, the doors face interestingly different directions, the journeys cluster and scatter — patterns spoken of with delight and without a single comparison of worth, because an atlas is not a league table. Guides reclaim their maps from the atlas in slate order, collecting their listeners' tour cards as they go — the session's only souvenir, and it belongs to the guide entire. Maps freely given to the session's folder are registered on the slate with their makers' names and the folder is stored where the room's next session can be introduced to this one, because that is what an atlas is for: the next new country will not be the only stranger at the table.",
       "Closing the session, the legend taken down last: the host reads the slate back entire — countries toured, stations given, maps foldered by consent and maps taken home, in the same tone for both — and the room's compass rose, if the early finishers made one, is offered to the folder or to the room's wall by the crew's vote. The tell-back is said with the blank legend cards still on the table: 'This morning we were names on a register. Now we are countries. We drew the places that made us — the kitchens and roads, the waters and the doors — we taught each other one symbol nobody else has, we toured three stations apiece like guides who respect their own borders, and the blank parts of our maps stayed blank, unasked, entire. Draw the country only you know. This room has seen it now — the parts you chose to show — and a country that has been toured is not a stranger's anymore.' Maps leave in their makers' hands or into the folder by the makers' word, tour cards go to their guides, and the slate is filed with the folder where the atlas's next session will find the whole geography in one place."],
      "A one-symbol version (a very short session or a very new room): every map is a single place — the star alone, drawn large — toured in one station each, with the full legend and blank-country law taught entire, ready to grow countries next time.",
      "A hopes-only version (a room where present geography is tender): every map is drawn in doors — places meant to be reached, journeys planned, waters not yet found — because a country made entirely of intentions is still a true introduction, and sometimes the most honest one in the room.",
      safety="The blank-country law is this record's safety system and it admits no exceptions: no member is ever asked — by the host, by a listener, by a question card, by a joke — to explain, label or apologise for an unlabelled region, a missing home place, a country drawn fictional, or a tour that passes a station by; the host retires any question that reaches for a blank, kindly and on the spot, and the retirement is final and unanalysed. Maps are personal documents and are handled as such: they are never photographed, scanned, pinned up or passed around without their maker's explicit consent for that exact use, they leave in their makers' hands by default, and a map left behind by accident is foldered unread by the host and returned in private — the session's curiosity is never an excuse written afterwards. Content follows the room's standing care: a map may hold a place of grief or difficulty entirely lawfully, its maker tours only what they choose, and the host's attention to a quiet guide is one neutral offer of a pass, made once — a passed tour is entered on the slate without commentary and the session moves on with genuine warmth, because the right to be unintroduced is the foundation every real introduction in this room stands on. Drawing tools are the room's ordinary safe kit; the session's real hazards are social, and they are governed by law, rehearsal and the host's early, kind interventions, in that order.",
      copy_free=True, no_elimination=True,
      inclusion="A map introduction is built from doors other introductions do not have: the whole performance can be drawn and toured from a seat, a map can be toured by its maker in speech, in writing read aloud by the host at the maker's dictation, or by the maker's own finger travelling the stations in silence while the host names each legend symbol as it is reached — a silent tour is a complete tour, and the slate records it in the same ink. Drawing is judged by no standard but legibility to its own legend: labelled boxes, dictated maps drawn by a partner's hand under the maker's direction, maps in a single colour or in relief with raised lines — all are countries entire, and the partner-scribe, where one serves, holds an honoured office credited on the slate, because the country is the maker's even when the pencil was borrowed. Listeners' tour cards can be written, drawn or dictated, the atlas round is read aloud by the host so its patterns reach every member, and consent for the atlas and the folder is asked in a form every member can answer privately — a card turned face down is a no, counted without a glance. Nobody's introduction depends on disclosing: the blank-country law is restated at every stage, and a map consisting of one door and three blank counties is toured, applauded and filed — where its maker wishes — with exactly the ceremony of the densest atlas page in the room."),
    # ---------------- Holidays, just teens (holidays age-13/14 primary 10 -> 11, St. Patrick's tag 6 -> 7) ----------------
    A("celtic-knot-drawing-studio", "Celtic Knot Drawing Studio",
      "For St. Patrick's Day, teens draw true Celtic knots on a dot grid: one unbroken line woven over and under itself, checked crossing by crossing.",
      ["holidays"], (13, 14), (4, 16), (45, 60), ["indoor"],
      ["dot-grid paper ruled true, or plain paper and the patience to rule it (the grid is the knot's skeleton and it is not negotiable: dots evenly spaced, rows counted before a line is drawn — a knot built on a wandering grid wanders in every crossing, and this studio rules its grids the way it checks its weaves, before it needs them)", "pencils, erasers that forgive, and one dark pen per member for the final inking (the studio's order is pencil until proven, pen when true: the weave is drawn, checked crossing by crossing, repaired in pencil — and only then inked, because ink is a knot's signature and a signature is not written over a guess)", "the worked examples — one simple plait and one true knot drawn large by the studio's keeper in advance, with their crossings marked (the examples are teaching instruments, shown entire and then pinned where the room can study them; the studio is honest that it learns this Irish and Scottish tradition from its published geometry, as beginners, with respect)", "the crossing-check cards — the studio's one law printed plainly: at every crossing, the strand that passed OVER must pass UNDER at its next crossing, and the card shows a checked run of crossings ticked in sequence (the alternation is the whole knot: break it anywhere and the weave lies, so the studio checks as it draws, crossing by crossing, never in a hopeful rush at the end)"],
      False, "Rule the grids before you invite a single knot, and rule them as the session's first craft act, together: dots counted aloud in the first rows, spacing checked by a partner's eye, because every later frustration in this studio is a grid error wearing a knot's clothing. Teach the tradition's frame at setup with the same care as its geometry: these interlace patterns come from Irish and wider Celtic art many centuries deep, carried in stone, metal and illuminated manuscripts; the studio learns their drawing method from published sources, as St. Patrick's Day guests of the tradition, and its respect is accuracy — real alternation, real counting, no pretend knotwork of squiggles blessed with a shamrock. Set the session's order now and write it on the board: plait first (the simple over-under braid every member completes), the true knot second for those the plait releases, checking third and always, inking last — because a studio that inks first and checks later produces beautiful false knots, and this one's whole pride is that its knots are true. Agree the studio's temperament law before pencils move: unpicking with an eraser is the craft's normal motion, a found error is a credit announced without shame, and speed is not a category anyone in this room is competing in.",
      ["The framing, the two worked examples pinned where the light finds them: 'One line, no beginning it will admit to. Look at the knot on the board: a single strand, travelling its grid, diving under a crossing, rising over the next, under, over, all the way home to where it started — which it will not point out to you. That alternation is not decoration. It is the knot's entire claim to be a knot, and it can be checked — by you, crossing by crossing, with a finger and the law on the card: over, then under, then over, never twice the same. Break the alternation once and you have drawn a rope lying on itself and called it weaving. Keep it everywhere and the drawing does the thing real knots do: it holds together by its crossings. Today we draw them truly or not at all. A plait first, until the rhythm is in the hand. Then, for those the plait releases, a closed knot on the grid, checked as it grows. Pencil until proven, pen when true — and the errors we find will be announced in this room like honours, because a found error is a knot saved.' The keeper traces the big knot's strand with one finger at teaching pace, calling the crossings aloud — over, under, over — and the room answers the last three before the first grid is touched.",
       "The plait, every member's first completed weave: on a short grid, the studio draws the simple braid together — strand entering, crossing, crossing, exiting — slowly, the count spoken, each crossing checked by its maker against the card before the next is drawn, because the plait is not a warm-up to be endured but the whole law practised at merciful length. Members whose plait runs true help as checkers at neighbouring grids — the studio's first office — reading crossings aloud for a drawer whose eyes have gone pattern-blind, which happens to every weaver by the third row and is named in the framing so nobody mistakes it for failure. When a plait is finished and checked entire, it is inked entire in the session's small ceremony: its maker inks, its checker witnesses, and the plait goes up on the board of true weaves, where it stays all session — not the best plaits, all of them, in finishing order, because the board is a census of the law kept, not a podium.",
       "The true knot, drawn on the closed grid by those the plait releases: the keeper demonstrates the construction once, slowly — the grid's dots connected in the method's stated order, walls and breaks placed by the published pattern for a small closed knot, the strand's path pencilled light until its whole journey exists — and then the room's discipline changes key: draw a stretch, check a stretch, the finger travelling every new crossing back to the last certainty, because a closed knot's error hides better the further the strand has travelled from it. Members choose their knot's size by honest appetite: a small knot finished true outweighs a grand one abandoned hopeful, and the studio says so at the choice, in the open. Checkers rotate by the board's order; a checker who finds a break announces it as the framing taught — 'a crossing to look at', never a verdict on its drawer — and the repair is drawn by the strand's own maker, eraser working back to the last true crossing, because a knot repaired by another hand teaches its maker only that someone else can weave.",
       "The inking and the strand-trace, the studio's proof: a knot is inked only when its maker and its checker have traced its single strand together, finger on the line, from any starting crossing all the way home, calling the alternation entire — over, under, over — without one break, one lift of the finger, or one merciful skip. A knot that fails its trace returns to pencil without ceremony and its trace is re-run after repair; a knot that passes is inked by its maker in one unhurried sitting, the pen following the proven path, and signed on its margin with the date and the checker's initials beside the maker's, because a true knot in this studio always has two names on it: the hand that drew it and the eyes that proved it. Inked knots join the board of true weaves, and the keeper reads the board's census aloud — plaits, knots, repairs counted and honoured as a number, not hidden as a history.",
       "Closing the studio, the strand traced once more by the whole room: the keeper's own demonstration knot — drawn during the session, at the front, where its errors were as public as anyone's — is traced entire by the room's voices together, crossing by crossing, to its home. The tell-back is said with the board of true weaves full in view: 'This morning a knot was a pretty squiggle none of us could prove. Now this board holds weaves that have been traced strand by strand and found true — over, under, over, all the way home — by their makers and their checkers together. We ruled our grids before we trusted them, we announced our errors like honours, we inked nothing we had not proven, and the tradition we visited for its saint's day was repaid in the only currency it accepts: accuracy. One line, no beginning it will admit to — and not one loose end on this board it has not earned.' Grids, cards and examples are filed together, unfinished knots are kept by their makers or filed at their word for a returning studio, and the board is photographed only with its makers' consent, names and all, or not at all."],
      "A plait-only version (a short hour or a very first studio): the braid drawn, checked and inked at three lengths, the law entire at the merciful scale — because a true plait is this craft complete, and the knot will keep for a room that has earned it.",
      "A panel version (a returning studio): makers join their true knots in a shared border panel for the room's St. Patrick's Day display, each knot traced and signed before it is mounted — the panel is only ever as true as its least-checked knot, and its makers say so on its card.",
      safety="This studio's hazards are small, sharp and honest, and they are governed plainly: compasses and ruling pins, where the grids are ruled with them, are tools counted out and back by name, points travelling down, and a member who rules with a ruler and a pencil alone is using the studio's full standard kit — no apology is owed for the safest instrument on the table. Pens and inks are the room's ordinary washable school stock; ink on skin is a laundry matter, never scrubbed with anything but soap and water, and the studio's one chemical law is that no solvent, correction fluid beyond the room's standard stock, or craft knife enters the knot table under any flag of authenticity. Posture and light are the real ergonomics of close work: grids are lit by the best light the room can arrange at setup, the keeper calls a stretch-and-look-away break at the session's middle whether anyone asks or not, because eyes that have gone pattern-blind are a safety matter for the weave and a comfort matter for their owner — and a member whose eyes or hands are done may hold the checker's office for the rest of the studio at full standing, the board's census crediting their proofs by name. The tradition framing is a care law too: jokes at the expense of the culture whose art is being learned end the joker's turn until the keeper is satisfied the room's respect is restored — the studio visits this tradition as a guest, and guests are governed.",
      tags=STPATS, copy_free=True, no_elimination=True,
      inclusion="Weaving on paper divides its honours between the drawing hand and the proving eye, and this studio's highest office belongs to the eye: the checker — tracer of strands, caller of crossings, witness of inkings — works from any seat, with a finger, a pointer, or a voice directing a partner's finger along the line, and a knot's margin carries the checker's initials at the same size as its maker's, because truth in this room is a two-person craft. Drawing adapts at the table: grids can be ruled large for hands and eyes that prefer them, knots can be drawn at double scale with the alternation entire, a maker may dictate a knot's path while a scribe's pencil travels it — the path is still the maker's, checked by the same law — and tracing a strand aloud, calling over and under in sequence, is a full way of weaving for a member whose hands are not drawing today. The board of true weaves takes every finished scale — plait or knot, large or small — in finishing order, the census read without ranking, and unfinished knots are filed at their makers' word as works the next studio can honourably resume. Nobody's session depends on inking: a knot proven in pencil and still being repaired at the close has lived the studio's whole discipline, and the closing reads its maker's name among the weavers entire."),
]

COLLECTION = {
    "id": "just-teens-fifth-time",
    "title": "Just Teens, a Fifth Time",
    "glyph": "🌗",
    "when_to_use": "The fifth shelf banded for thirteen- and fourteen-year-olds ONLY — the floor-to-nine shelf: a season's heat counted in degree-days and a budburst predicted in ink, one yard mapped into its many microclimates, a three-team game with one enormous ball, a room conducted by learned hands, a museum of loaned objects on one table, counted sashiko stitches in indigo and white, introductions toured across drawn countries, and a true Celtic knot traced strand by strand. Reach for it when the teen room needs the band's eight thinnest categories — seasons, outdoor, movement, music, rainy-day, crafts, icebreakers and holidays — written for the room itself, not borrowed from younger shelves.",
    "picks": [
        {"id": "growing-degree-day-ledger", "note": "A plant keeps its calendar in heat, not in dates — daily degree-days in one ledger, a prediction in ink, and the plant itself does the grading."},
        {"id": "microclimate-map-survey", "note": "One yard holds many climates — twelve stations read inside one ten-minute window, drawn as a map that anyone can check with a thermometer."},
        {"id": "kin-ball-first-session", "note": "Three teams, one ball, no owner — serve by calling a colour, lift everything, and win by being the team the ball cannot catch out."},
        {"id": "conducting-patterns-studio", "note": "Your hands speak first; the room answers — patterns in two, three and four, cues that land, and a cut-off whose silence counts as music."},
        {"id": "one-table-micro-museum", "note": "A museum is an argument made of objects — loans under law, labels checked by their owners, and every object signed home entire."},
        {"id": "sashiko-stitch-sampler-studio", "note": "Small stitches, counted rows, no loose ends — a centuries-old stitch learned on scrap first, its wandering rows unpicked by their own makers."},
        {"id": "personal-map-introductions", "note": "Draw the country only you know — three-station tours of the places that made you, and blank regions that stay blank, unasked, entire."},
        {"id": "celtic-knot-drawing-studio", "note": "One line, no beginning it will admit to — over, under, over, traced all the way home before a drop of ink is allowed near it."},
    ],
}


def tokens(s):
    return set(re.findall(r"[a-z0-9]+", s.lower()))


def main():
    path = os.path.join(DATA, "activities.json")
    acts = json.load(open(path))
    existing = {a["id"] for a in acts}
    corpus = [(a["id"], tokens(a["name"] + " " + a["tagline"])) for a in acts]
    for rec in PACK:
        t = tokens(rec["name"] + " " + rec["tagline"])
        worst, wid = 0.0, None
        for oid, ot in corpus:
            j = len(t & ot) / max(1, len(t | ot))
            if j > worst:
                worst, wid = j, oid
        print(f"jaccard {rec['id']}: worst {worst:.2f} vs {wid}")
        assert worst < 0.55, f"near-duplicate: {rec['id']} vs {wid} ({worst:.2f})"
        assert rec["age_min"] == 13 and rec["age_max"] == 14, f"not 13-14: {rec['id']}"
        assert len(rec["tagline"]) <= 160, f"tagline too long: {rec['id']} ({len(rec['tagline'])})"
        words = len(json.dumps(rec).split())
        print(f"words {rec['id']}: {words}")
        assert words >= 1300, f"record under the long-form bar: {rec['id']} ({words})"
    added = 0
    for rec in PACK:
        if rec["id"] in existing:
            print("skip (exists):", rec["id"])
            continue
        acts.append(rec)
        existing.add(rec["id"])
        added += 1
    json.dump(acts, open(path, "w"), indent=1, ensure_ascii=False)
    print(f"added {added} activities; total now {len(acts)}")

    cpath = os.path.join(DATA, "collections.json")
    cdata = json.load(open(cpath))
    colls = cdata["collections"]
    if COLLECTION["id"] not in {c["id"] for c in colls}:
        colls.append(COLLECTION)
        cdata["collections"] = colls
        json.dump(cdata, open(cpath, "w"), indent=1, ensure_ascii=False)
        print(f"collection added: {COLLECTION['id']} ({len(COLLECTION['picks'])} picks); collections now {len(colls)}")
    else:
        print("collection exists, skipped; collections:", len(colls))


if __name__ == "__main__":
    main()
